const winston = require('winston');

// SECURITY NOTE: Never log the Authorization header, token values, or any secret.
// This logger must not be used to record sensitive authentication data.

// NOTE: The logs/ directory must exist before the application starts.
// The startup script or Dockerfile is responsible for creating it (e.g., mkdir -p logs).

const { combine, timestamp, errors, splat, json, colorize, printf } = winston.format;

const NODE_ENV = process.env.NODE_ENV || 'development';

const resolveLogLevel = () => {
  if (process.env.LOG_LEVEL) {
    return process.env.LOG_LEVEL;
  }
  return NODE_ENV === 'production' ? 'info' : 'debug';
};

const logLevel = resolveLogLevel();

const jsonFormat = combine(
  timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  errors({ stack: true }),
  splat(),
  json()
);

const consoleFormat = combine(
  timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  errors({ stack: true }),
  splat(),
  colorize({ all: true }),
  printf(({ timestamp, level, message }) => {
    return `${timestamp} ${level.toUpperCase()} ${message}`;
  })
);

const transports = [];

if (NODE_ENV !== 'production') {
  transports.push(
    new winston.transports.Console({
      level: logLevel,
      format: consoleFormat,
    })
  );
}

transports.push(
  new winston.transports.File({
    filename: 'logs/error.log',
    level: 'error',
    format: jsonFormat,
    maxsize: 5242880,
    maxFiles: 5,
  })
);

transports.push(
  new winston.transports.File({
    filename: 'logs/combined.log',
    level: logLevel,
    format: jsonFormat,
    maxsize: 10485760,
    maxFiles: 10,
  })
);

const logger = winston.createLogger({
  level: logLevel,
  defaultMeta: {
    service: process.env.npm_package_name || 'api-hola',
    environment: NODE_ENV,
  },
  transports,
  exceptionHandlers: [
    new winston.transports.File({
      filename: 'logs/exceptions.log',
      format: jsonFormat,
    }),
  ],
  rejectionHandlers: [
    new winston.transports.File({
      filename: 'logs/rejections.log',
      format: jsonFormat,
    }),
  ],
});

const stream = {
  write: (message) => {
    logger.http(message.trim());
  },
};

module.exports = logger;
module.exports.stream = stream;

const jwt = require('jsonwebtoken');
const logger = require('../config/logger');

const verifyToken = (req, res, next) => {
  if (!process.env.JWT_SECRET || process.env.JWT_SECRET.trim() === '') {
    logger.error({
      type: 'MISSING_JWT_SECRET',
      message: 'JWT_SECRET no está definido en las variables de entorno',
      ip: req.ip,
      method: req.method,
      url: req.originalUrl,
      timestamp: new Date().toISOString(),
    });
    return res.status(500).json({
      status: 'error',
      message: 'Configuración de seguridad incompleta',
    });
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    logger.warn({
      type: 'MISSING_OR_INVALID_TOKEN_FORMAT',
      message: 'Header Authorization ausente o con formato inválido',
      ip: req.ip,
      method: req.method,
      url: req.originalUrl,
      timestamp: new Date().toISOString(),
    });
    return res.status(401).json({
      status: 'error',
      message: 'Token no proporcionado o formato inválido',
    });
  }

  const token = authHeader.split(' ')[1];

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    if (error instanceof jwt.TokenExpiredError) {
      logger.warn({
        type: 'TOKEN_EXPIRED',
        message: 'El token JWT ha expirado',
        ip: req.ip,
        method: req.method,
        url: req.originalUrl,
        timestamp: new Date().toISOString(),
      });
      return res.status(401).json({
        status: 'error',
        message: 'Token expirado',
      });
    }

    if (error instanceof jwt.JsonWebTokenError) {
      logger.warn({
        type: 'INVALID_TOKEN',
        message: 'El token JWT es inválido',
        ip: req.ip,
        method: req.method,
        url: req.originalUrl,
        timestamp: new Date().toISOString(),
      });
      return res.status(401).json({
        status: 'error',
        message: 'Token inválido',
      });
    }

    logger.error({
      type: 'UNEXPECTED_AUTH_ERROR',
      message: 'Error inesperado durante la autenticación',
      ip: req.ip,
      method: req.method,
      url: req.originalUrl,
      timestamp: new Date().toISOString(),
    });
    return res.status(500).json({
      status: 'error',
      message: 'Error interno de autenticación',
    });
  }
};

module.exports = { verifyToken };

const rateLimit = require('express-rate-limit');
const logger = require('../config/logger');

// NOTE: En ambientes de producción con múltiples instancias se debe reemplazar
// el store por defecto por un store externo como Redis usando el paquete rate-limit-redis.

const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 900000,
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    status: 429,
    error: 'Too Many Requests',
    message:
      'Has superado el límite de solicitudes permitidas. Por favor, intenta nuevamente más tarde.',
  },
  handler: (req, res, next, options) => {
    logger.warn('Rate limit exceeded', {
      ip: req.ip,
      method: req.method,
      url: req.originalUrl,
      message: 'Rate limit exceeded',
    });
    res.status(429).json(options.message);
  },
  keyGenerator: (req) => req.ip,
  skip: (req) => false,
});

module.exports = limiter;

const { query, header, validationResult } = require('express-validator');

const validateHolaInput = [
  header('authorization')
    .trim()
    .notEmpty()
    .withMessage('Authorization header is required and must have format Bearer token')
    .matches(/^Bearer\s.+/)
    .withMessage('Authorization header is required and must have format Bearer token'),

  query('lang')
    .optional()
    .trim()
    .escape()
    .isLength({ max: 10 })
    .withMessage('lang must be an alphabetic value of maximum 10 characters')
    .isAlpha()
    .withMessage('lang must be an alphabetic value of maximum 10 characters'),
];

const handleValidationErrors = (req, res, next) => {
  const result = validationResult(req);

  if (!result.isEmpty()) {
    const errors = result.array().map((err) => ({
      field: err.path || err.param,
      message: err.msg,
    }));

    return res.status(422).json({
      status: 'error',
      message: 'Validation failed',
      errors,
    });
  }

  next();
};

module.exports = { validateHolaInput, handleValidationErrors };

